import React, { useState } from "react";
import { getRecommendation, sendFeedback } from "../api";

export default function ChatbotPage({ styleInfo, onAddToHistory }) {
  const [query, setQuery] = useState("");
  const [chat, setChat] = useState([]);
  const [recommendation, setRecommendation] = useState(null);
  const [feedback, setFeedback] = useState("");
  const [loading, setLoading] = useState(false);
  const [feedbackLoading, setFeedbackLoading] = useState(false);

  const handleQuery = async () => {
    setLoading(true);
    const req = { ...styleInfo, user_query: query };
    try {
      const res = await getRecommendation(req);
      setRecommendation(res.suggestion);
      setChat([...chat, { type: "user", text: query }, { type: "stylist", ...res.suggestion }]);
    } catch {
      setChat([...chat, { type: "user", text: query }, { type: "error", text: "Could not get recommendation." }]);
    } finally {
      setLoading(false);
    }
  };

  const handleFeedback = async () => {
    setFeedbackLoading(true);
    try {
      const req = { ...styleInfo, user_query: query, feedback };
      const res = await getRecommendation(req);
      setRecommendation(res.suggestion);
      setChat([...chat, { type: "user", text: feedback }, { type: "stylist", ...res.suggestion }]);
    } catch {
      setChat([...chat, { type: "user", text: feedback }, { type: "error", text: "Could not update recommendation." }]);
    } finally {
      setFeedbackLoading(false);
    }
  };

  return (
    <div className="chatbot-page">
      <h2>Ask for an Outfit</h2>
      <input value={query} onChange={e => setQuery(e.target.value)} placeholder="What do you need an outfit for?" />
      <button onClick={handleQuery} disabled={loading || !query}>{loading ? "Loading..." : "Ask Stylist"}</button>
      <div className="chat-window">
        {chat.map((msg, idx) =>
          msg.type === "user" ? (
            <div key={idx} className="chat-user">You: {msg.text}</div>
          ) : msg.type === "stylist" ? (
            <div key={idx} className="chat-stylist">
              <div><b>Stylist:</b></div>
              <div>Top: {msg.top}</div>
              <div>Bottom: {msg.bottom}</div>
              {msg.outerwear && <div>Outerwear: {msg.outerwear}</div>}
              <div style={{ fontStyle: "italic", marginTop: 4 }}>{msg.comment}</div>
            </div>
          ) : (
            <div key={idx} className="chat-error">{msg.text}</div>
          )
        )}
      </div>
      {recommendation && (
        <div className="feedback-section">
          <textarea value={feedback} onChange={e => setFeedback(e.target.value)} placeholder="Feedback (e.g. change top, prefer lighter color, etc)" />
          <button onClick={handleFeedback} disabled={feedbackLoading || !feedback}>{feedbackLoading ? "Updating..." : "Send Feedback"}</button>
          <button onClick={() => onAddToHistory(recommendation)} style={{ marginLeft: 8 }}>Add to History</button>
        </div>
      )}
    </div>
  );
}
